import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/mockProvider.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

// @spec specs/hal-engine-config-hooks/spec.md#9
it('preserves a thrown string as the onError cause and caller rejection', async () => {
  const errors: Error[] = [];
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'Test assistant'}),
    undefined,
    {
      hooks: {
        beforeSession: async () => {
          throw 'string boom';
        },
        onError: async (_session, error) => {
          errors.push(error);
        },
      },
    }
  );
  const rejection: unknown = await orchestrator.processMessage(session).catch((reason: unknown) => reason);

  expect({errors, rejection}).toEqual({
    errors: [expect.objectContaining({message: 'string boom', cause: 'string boom'})],
    rejection: 'string boom',
  });
});
EOF
timeout 300 npm test -- --runTestsByPath src/orchestration/onErrorCause.test.ts --runInBand"
